const DATA=window.KOSHRA_DATA;const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];const page=(location.pathname.split('/').pop()||'index.html').replace('.html','');const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);const getCart=()=>JSON.parse(localStorage.getItem('koshra-cart')||'[]');const saveCart=c=>{localStorage.setItem('koshra-cart',JSON.stringify(c));renderCartCount();};const image=(src,alt,cls='')=>`<img class="${cls}" src="${src}" alt="${alt}" loading="${src.includes('hero')?'eager':'lazy'}">`;
const announcements=['Complimentary message card with every gift box.','Corporate orders now open for Diwali.','Pan-India delivery available.'];
function header(){return `<div class="announcement"><span>${announcements.join('<br>')}</span></div><header class="site-header"><button class="menu-button" aria-label="Open menu">☰</button><a class="brand" href="index.html">KOSHRA<small>Gifting<br>House</small></a><nav class="desktop-nav" aria-label="Primary navigation"><div class="nav-drop"><button aria-haspopup="true">Shop ↓</button><div class="mega"><a href="shop.html">Shop all</a><a href="shop.html?tag=bestseller">Bestsellers</a><a href="gift-boxes.html">Gift boxes</a><a href="shop.html?category=Dry%20Fruits">Dry fruits</a><a href="shop.html?category=Dates">Dates</a><a href="collections.html?occasion=wellness">Wellness</a><a href="collections.html?occasion=diwali">Festive</a><a href="build-your-box.html">Build your box</a><div class="mega-image">${image('assets/koshra-unboxing.jpg','Hands opening a personalised KOSHRA dry-fruit box')}</div></div></div><a href="gift-boxes.html">Gift boxes</a><a href="build-your-box.html">Build your box</a><a href="corporate-gifting.html">Corporate</a><div class="nav-drop"><button aria-haspopup="true">Occasions ↓</button><div class="mega"><a href="collections.html?occasion=diwali">Diwali</a><a href="corporate-gifting.html">Corporate gifting</a><a href="collections.html?occasion=employees">Employee appreciation</a><a href="collections.html?occasion=clients">Client gifting</a><a href="collections.html?occasion=weddings">Weddings</a><a href="collections.html?occasion=birthdays">Birthdays</a><a href="collections.html?occasion=new-year">New Year</a><div class="mega-image">${image('assets/koshra-corporate-desk.jpg','KOSHRA gift box prepared for a corporate recipient')}</div></div></div><a href="about.html">Our story</a></nav><div class="header-tools"><button class="icon-button search-toggle" aria-label="Search"><span class="search-text">Search</span><span aria-hidden="true">⌕</span></button><a class="account-link" href="account.html">Account</a><button class="icon-button cart-toggle" aria-label="Open cart"><span class="bag-text">Bag</span><span class="cart-count">0</span></button></div></header>`}
function footer(){return `<footer class="site-footer"><div class="footer-top"><div class="footer-brand"><h2>KOSHRA</h2><p>Thoughtful dry-fruit gifts for personal moments, teams, clients and Indian celebrations.</p><a class="btn light small" href="../index.html">Back to catalogue ↗</a></div><div class="footer-col"><h3>Shop</h3><a href="shop.html">All gifts</a><a href="gift-boxes.html">Gift boxes</a><a href="build-your-box.html">Build your box</a><a href="collections.html">Collections</a></div><div class="footer-col"><h3>Corporate</h3><a href="corporate-gifting.html">Services</a><a href="corporate-quote.html">Request pricing</a><a href="packaging-personalisation.html">Personalisation</a><a href="track-order.html">Track an order</a></div><div class="footer-col"><h3>Customer care</h3><a href="delivery.html">Delivery</a><a href="faq.html">FAQs</a><a href="contact.html">Contact</a><a href="shipping-returns.html">Shipping & returns</a></div><form class="newsletter"><h3>Notes from the gifting desk</h3><p>New collections, festive timelines and corporate ordering dates.</p><input type="email" required placeholder="Email address" aria-label="Email address"><button class="btn light small" type="submit">Subscribe</button></form></div><div class="footer-bottom"><span>© 2026 KOSHRA · Concept storefront</span><span>GSTIN: [CLIENT TO PROVIDE] · FSSAI: [CLIENT TO PROVIDE]</span><span>hello@[brand-domain].in · +91 [NUMBER]</span></div></footer>`}
function overlays(){return `<aside class="mobile-nav" aria-hidden="true"><div class="mobile-top"><span class="brand">KOSHRA</span><button class="close-button" data-close aria-label="Close menu">×</button></div><a href="shop.html">Shop all</a><a href="gift-boxes.html">Gift boxes</a><a href="build-your-box.html">Build your box</a><a href="corporate-gifting.html">Corporate gifting</a><a href="collections.html">Occasions</a><a href="about.html">Our story</a><a href="contact.html">Contact</a></aside><aside class="drawer search-panel" aria-hidden="true"><div class="mobile-top"><h2>Search KOSHRA</h2><button class="close-button" data-close aria-label="Close search">×</button></div><label>Product, ingredient or occasion<input id="site-search" placeholder="Try “client gifts”"></label><div id="search-results"></div></aside><aside class="cart-drawer" aria-hidden="true"><div class="mobile-top"><h2>Your gift bag</h2><button class="close-button" data-close aria-label="Close cart">×</button></div><div id="drawer-cart"></div></aside><div class="backdrop" data-close></div>`}
function initShell(){$('#site-shell').innerHTML=header();$('#overlay-root').innerHTML=overlays()+footer();renderCartCount();$('.menu-button').onclick=()=>openPanel('.mobile-nav');$('.search-toggle').onclick=()=>openPanel('.search-panel');$('.cart-toggle').onclick=()=>{renderDrawerCart();openPanel('.cart-drawer')};$$('[data-close]').forEach(x=>x.onclick=closePanels);$('.newsletter').onsubmit=e=>{e.preventDefault();e.target.reset();toast('You are on the gifting list — demo only')};$('#site-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();const hits=DATA.products.filter(p=>(p.name+p.description+p.contents).toLowerCase().includes(q)).slice(0,5);$('#search-results').innerHTML=hits.map(p=>`<a class="cart-drawer-line" href="product.html?slug=${p.slug}">${image(p.image,p.name)}<span><strong>${p.name}</strong><br>${money(p.price)}</span></a>`).join('')||(q?'<p>No gifts match that search.</p>':'')});}
function openPanel(s){closePanels();$(s).classList.add('open');$(s).setAttribute('aria-hidden','false');$('.backdrop').classList.add('open');document.body.classList.add('locked')}function closePanels(){$$('.mobile-nav,.drawer,.cart-drawer').forEach(x=>{x.classList.remove('open');x.setAttribute('aria-hidden','true')});$('.filters')?.classList.remove('mobile-open');$('.backdrop')?.classList.remove('open');document.body.classList.remove('locked')}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function renderCartCount(){const n=getCart().reduce((a,b)=>a+b.qty,0);$$('.cart-count').forEach(x=>x.textContent=n)}function addCart(id,qty=1,custom={}){const cart=getCart();const match=cart.find(x=>x.id===id&&JSON.stringify(x.custom)===JSON.stringify(custom));if(match)match.qty+=qty;else cart.push({id,qty,custom});saveCart(cart);toast('Gift added to your bag');}
function renderDrawerCart(){const cart=getCart(),root=$('#drawer-cart');if(!cart.length){root.innerHTML='<div class="cart-empty"><p>Your bag is ready for a thoughtful first choice.</p><a class="btn forest" href="shop.html">Shop gift boxes</a></div>';return}root.innerHTML=cart.map((x,i)=>{const p=DATA.products.find(p=>p.id===x.id);return `<div class="cart-drawer-line">${image(p.image,p.name)}<div><strong>${p.name}</strong><br><small>Qty ${x.qty} · ${money(p.price*x.qty)}</small><br><button class="text-button" data-remove="${i}">Remove</button></div></div>`}).join('')+`<a class="btn forest block" href="cart.html">Review bag</a>`;$$('[data-remove]',root).forEach(b=>b.onclick=()=>{const c=getCart();c.splice(+b.dataset.remove,1);saveCart(c);renderDrawerCart()})}
function productCard(p){return `<article class="product-card" data-id="${p.id}" data-price="${p.price}" data-category="${p.category}" data-tags="${p.tags.join(' ')}"><a class="product-image" href="product.html?slug=${p.slug}">${image(p.image,`${p.name}, ${p.contents}`,`crop-${p.crop}`)}${p.tags.includes('bestseller')?'<span class="product-badge">Bestseller</span>':''}</a><div class="product-info"><h3><a href="product.html?slug=${p.slug}">${p.name}</a></h3><p>${p.description}</p><div class="product-meta">${p.contents}</div><div class="product-price"><strong>${money(p.price)}</strong><span>${p.personalise?'Personalisation available':''}</span></div><div class="card-actions"><button class="btn small quick-add" data-id="${p.id}">Quick add</button><a class="btn small" href="product.html?slug=${p.slug}">Details</a></div></div></article>`}
function sectionHead(k,h,p){return `<div class="section-head"><div><p class="kicker">${k}</p><h2 class="section-title">${h}</h2></div><p>${p}</p></div>`}
function home(){return `<section class="hero"><div class="hero-copy"><p class="kicker">Premium dry-fruit gifting · India</p><h1 class="display">Thoughtful gifts,<br><em>beautifully presented.</em></h1><p class="lede">Premium dry-fruit collections designed for clients, teams, celebrations and everyday moments of appreciation.</p><div class="hero-actions"><a class="btn forest" href="gift-boxes.html">Shop gift boxes</a><a class="btn" href="corporate-gifting.html">Explore corporate gifting</a></div><p class="trust-line">Custom branding · GST invoicing · Pan-India delivery</p></div><div class="hero-media">${image('assets/koshra-hero.jpg','Open KOSHRA forest-green gift box filled with almonds, cashews, pistachios, walnuts, dates and berries')}<p class="image-label">Six ingredients. One considered presentation. Message card included.</p></div></section>${giftFinder()}<section class="editorial-section"><div class="shell">${sectionHead('Find the right gesture','Gifts organised around the reason.','For clients, teams, celebrations and personal thank-yous. Different budgets and quantities should lead to genuinely different routes—not one endless product grid.')}<div class="collection-grid">${DATA.collections.slice(0,5).map(c=>`<a class="collection-card" href="${c.href}">${image(c.image,c.name)}<div class="collection-overlay"><h3>${c.name}</h3><p>${c.copy}</p></div></a>`).join('')}</div></div></section><section class="editorial-section"><div class="shell">${sectionHead('Bestselling boxes','Ready to give. Built to be remembered.','Retail pricing stays visible. For quantities above 25, the corporate route adds branding, address management and coordinated dispatch.')}</div><div class="product-rail">${DATA.products.slice(0,4).map(productCard).join('')}</div></section><section class="builder-feature"><div class="builder-media">${image('assets/koshra-unboxing.jpg','Hands opening a personalised KOSHRA gift box with dry fruits and message card')}</div><div class="builder-copy"><p class="kicker">Build your own box</p><h2 class="section-title">Choose every part of the gift.</h2><ol class="numbered-process"><li><b>01</b><span>Choose your box and number of compartments.</span></li><li><b>02</b><span>Select dry fruits, dates, berries and considered extras.</span></li><li><b>03</b><span>Add a recipient name, message or company branding.</span></li><li><b>04</b><span>Choose recipients, addresses and delivery dates.</span></li></ol><a class="btn forest" href="build-your-box.html">Build your gift box</a></div></section><section class="corporate-feature"><div class="corporate-copy"><p class="kicker">Corporate gifting</p><h2 class="section-title">One thoughtful gift.<br>Fifty careful details.</h2><p class="lede">Custom logo sleeves, printed cards, engraved boxes, quantity pricing, GST invoices and multi-location dispatch managed as one programme.</p><div class="service-list">${['Logo sleeves and ribbons','Excel address upload','Scheduled delivery','GST invoicing','Packaging consultation','Dedicated coordination'].map(x=>`<span>${x}</span>`).join('')}</div><div class="hero-actions"><a class="btn light" href="corporate-gifting.html">View corporate gifting</a><a class="btn light" href="corporate-quote.html">Request a quote</a></div></div><div class="corporate-media">${image('assets/koshra-dispatch.jpg','Rows of KOSHRA gift boxes being prepared for corporate dispatch')}</div></section><section class="editorial-section"><div class="shell">${sectionHead('Three ways to order','The route changes with the quantity.','Direct checkout for smaller programmes; volume pricing and dedicated coordination when the project becomes operationally complex.')} ${tierTable()}</div></section><section class="packaging-story"><div class="packaging-photo">${image('assets/koshra-corporate-desk.jpg','Closed KOSHRA box with branded sleeve, ribbon and message card on an executive desk')}</div><div><p class="kicker">The packaging story</p><h2 class="section-title">Designed from first glance to final handful.</h2><p class="lede">The sleeve carries the sender. The box protects the ingredients. The card delivers the message. The internal order makes the opening feel considered.</p><div class="sequence"><span>Box</span><span>Contents</span><span>Message</span><span>Recipient</span></div><a class="btn" href="packaging-personalisation.html">See personalisation</a></div></section><section class="quote-placeholder"><div class="shell"><span class="placeholder-label">Illustrative testimonial — replace before launch</span><blockquote>“The right proof here should explain product quality, presentation and delivery coordination—not simply say the box looked nice.”</blockquote><footer>Approved client quote and role to be supplied</footer></div></section>${finalCTA()}`}
function giftFinder(){return `<form class="gift-finder"><div class="finder-grid"><div class="finder-intro"><p class="kicker">Gift finder</p><h2>Start with the practical details.</h2></div>${[['Budget',['Under ₹999','₹1,000–₹1,499','₹1,500–₹2,499','₹2,500–₹4,999','₹5,000+']],['Occasion',['Diwali','Employee appreciation','Client gifting','Wedding','Birthday','Thank you','Wellness','New Year']],['Recipient',['Clients','Employees','Leadership','Friends','Family','Wedding guests']],['Quantity',['1–9','10–49','50–199','200+']]].map(([n,o])=>`<div class="finder-field"><label>${n}</label><select name="${n.toLowerCase()}">${o.map(x=>`<option>${x}</option>`).join('')}</select></div>`).join('')}<button class="finder-submit">Find suitable gifts →</button></div></form>`}
function tierTable(){return `<div class="tier-table">${[['10–49 gifts','Order directly online.',['Ready-made boxes','Message card','Multiple addresses','GST invoice']],['50–199 gifts','Request corporate pricing.',['Volume pricing','Logo sleeves','Packaging consultation','Delivery coordination']],['200+ gifts','Create a custom programme.',['Custom boxes','Product sampling','Prototype approval','Dedicated support']]].map(([q,h,l])=>`<article class="tier-row"><strong>${q}</strong><h3>${h}</h3><ul>${l.map(x=>`<li>${x}</li>`).join('')}</ul></article>`).join('')}</div>`}
function finalCTA(){return `<section class="final-cta"><div><p class="kicker">Planning gifts for clients or your team?</p><h2 class="section-title">Bring the quantity, budget and date. We’ll shape the rest.</h2></div><div><p>Share the occasion, recipient count and preferred delivery date for suitable box and personalisation recommendations.</p><div class="hero-actions"><a class="btn light" href="corporate-quote.html">Request corporate pricing</a><a class="btn light" href="contact.html">Continue on WhatsApp</a></div></div></section>`}
function shop(title='Shop all gifts',filterCategory=''){const params=new URLSearchParams(location.search);const cat=filterCategory||params.get('category')||'';const tag=params.get('tag')||'';let products=DATA.products.filter(p=>(!cat||p.category===cat)&&(!tag||p.tags.includes(tag)));return `${pageHero('Gift catalogue',title,'Product information is structured for quick retail decisions and serious corporate comparison.','assets/koshra-hero.jpg')}<div class="shop-layout"><aside class="filters"><div class="filters-head"><h2>Filter</h2><button class="close-button filter-close" aria-label="Close filters">×</button></div>${[['Price',['Under ₹1,000','₹1,000–₹1,999','₹2,000–₹4,999','₹5,000+']],['Occasion',['Diwali','Client gifting','Employee gifting','Weddings']],['Product type',['Gift boxes','Dates','Dry fruits','Wellness']],['Details',['Personalisation','Vegan','Bestseller','Ready to dispatch']]].map(([h,a])=>`<div class="filter-group"><h3>${h}</h3>${a.map(x=>`<label><input type="checkbox" data-group="${h}" value="${x}"> ${x}</label>`).join('')}</div>`).join('')}<button class="btn small block clear-filters">Clear all</button></aside><section class="shop-main"><div class="shop-toolbar"><div><button class="btn small mobile-filter">Filter</button><span id="product-count">${products.length} gifts</span><div class="active-filters">${cat?`<span class="filter-chip">${cat} ×</span>`:''}${tag?`<span class="filter-chip">${tag} ×</span>`:''}</div></div><div><button class="icon-button view-toggle" data-view="grid" aria-label="Grid view">▦</button><button class="icon-button view-toggle" data-view="list" aria-label="List view">☷</button><select id="sort-products" aria-label="Sort products"><option value="featured">Featured</option><option value="low">Price low to high</option><option value="high">Price high to low</option><option value="name">New arrivals</option></select></div></div><div class="product-grid" id="shop-grid">${products.map(productCard).join('')}</div><div class="empty-state" id="empty-products" hidden><div><h2>No gifts match those filters.</h2><p>Clear the filters or request a custom corporate recommendation.</p><button class="btn forest clear-filters">Clear all filters</button></div></div></section></div>`}
function pageHero(k,h,p,img){return `<section class="page-hero"><div class="page-hero-copy"><div class="breadcrumbs"><a href="index.html">Home</a> / ${k}</div><p class="kicker">${k}</p><h1 class="display">${h}</h1><p class="lede">${p}</p></div><div class="page-hero-media">${image(img,h)}</div></section>`}
function collections(){return `${pageHero('Occasions','Choose the reason before the box.','Collections are organised by who receives the gift, what it needs to say and how many people it needs to reach.','assets/koshra-unboxing.jpg')}<section class="editorial-section"><div class="shell">${sectionHead('Curated routes','Six ways into the catalogue.','Use an occasion collection for a faster shortlist, or open the builder when the contents and presentation need to be specific.')}<div class="collection-grid">${DATA.collections.map(c=>`<a class="collection-card" href="${c.href}">${image(c.image,c.name)}<div class="collection-overlay"><h3>${c.name}</h3><p>${c.copy}</p></div></a>`).join('')}</div></div></section>`}
function productDetail(){const slug=new URLSearchParams(location.search).get('slug')||DATA.products[0].slug,p=DATA.products.find(x=>x.slug===slug)||DATA.products[0];return `<div class="product-detail"><section class="gallery" aria-label="Product gallery"><figure>${image(p.image,`${p.name}, primary presentation`)}</figure><figure>${image('assets/koshra-hero.jpg',`${p.name}, open box view`)}</figure><figure>${image('assets/dried-fruits-unsplash.jpg',`${p.name}, ingredient detail`)}</figure></section><section class="detail-panel"><div class="breadcrumbs"><a href="shop.html">Shop</a> / ${p.category}</div><p class="kicker">${p.stock}</p><h1>${p.name}</h1><p>${p.description}</p><div class="detail-price"><strong>${money(p.price)}</strong><span>Corporate from ${money(p.corporate)} · MOQ ${p.moq}</span></div><div class="detail-options"><label>Delivery date<input type="date" id="delivery-date"></label><label>Complimentary message card<textarea id="gift-message" rows="3" maxlength="180" placeholder="Write a short message"></textarea></label><label>Personalisation<select id="personalise"><option>Message card only</option><option>Recipient name on sleeve + ₹150</option><option>Company logo sleeve — corporate quote</option></select></label><div class="qty-row"><label>Quantity<input id="product-qty" type="number" min="1" value="1"></label><label>PIN code<input id="pin-check" inputmode="numeric" maxlength="6" placeholder="6-digit PIN"><small id="pin-result"></small></label></div><button class="btn forest block" id="add-product" data-id="${p.id}">Add to cart · ${money(p.price)}</button><button class="btn block" onclick="location.href='corporate-quote.html?product=${p.slug}'">Request bulk pricing</button></div><dl class="detail-facts"><div><dt>Inside</dt><dd>${p.contents}</dd></div><div><dt>Net quantity</dt><dd>${p.weight}</dd></div><div><dt>Compartments</dt><dd>${p.compartments}</dd></div><div><dt>Packaging</dt><dd>${p.material}</dd></div><div><dt>Shelf life</dt><dd>${p.shelf}</dd></div><div><dt>Dispatch</dt><dd>${p.dispatch}</dd></div></dl><div class="accordion">${[['What is inside',p.contents],['Ingredient & allergen information',p.allergens],['Packaging details',p.material+'. Packaging specifications must be verified before production.'],['Delivery','Pan-India delivery messaging is illustrative until logistics integration.'],['Corporate customisation',`Logo sleeve, ribbon and message-card options from ${p.moq} gifts.`]].map(([h,c])=>`<button aria-expanded="false">${h}<span>+</span></button><div class="accordion-panel">${c}</div>`).join('')}</div></section></div><div class="sticky-cart"><button class="btn forest" data-sticky-add="${p.id}">Add · ${money(p.price)}</button><a class="btn" href="corporate-quote.html">Bulk pricing</a></div><section class="editorial-section"><div class="shell">${sectionHead('You may also consider','Boxes for a similar gifting brief.','Compare contents, format and corporate minimum quantity before choosing.')}</div><div class="product-rail">${DATA.products.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join('')}</div></section>`}
function builder(){return `${pageHero('Build your box','A complete gift, configured step by step.','Choose the structure, contents, message, recipients and delivery plan. Your selections remain saved on this device.','assets/gift-wrapping-pexels.jpg')}<div class="builder-layout"><section><nav class="builder-progress" aria-label="Builder progress">${['Box','Contents','Personalise','Recipients','Delivery','Review'].map((x,i)=>`<button data-step="${i}" class="${i===0?'active':''}">${i+1}. ${x}</button>`).join('')}</nav><div class="builder-main">${builderSteps()}</div></section><aside class="builder-preview"><p class="kicker">Live configuration</p><h2 class="section-title">Your KOSHRA box</h2><div class="preview-box" id="preview-box"></div><div id="preview-details"><p>Choose a box to begin.</p></div><div class="preview-total"><span>Running total</span><strong id="builder-total">₹0</strong></div><p><small>Taxes and shipping calculated at review. Corporate pricing suggested above 50 gifts.</small></p></aside></div>`}
function builderSteps(){const boxes=[['Classic rigid box',4,595],['Premium wooden box',6,1895],['Sustainable kraft box',4,395],['Fabric-finish box',6,1295],['Festive trunk',8,2395],['Executive presentation box',6,1595]];return `<section class="builder-step active" data-builder-step="0"><p class="kicker">Step 1 of 6</p><h2 class="section-title">Choose the structure.</h2><div class="option-grid">${boxes.map(([n,c,p])=>`<button class="select-card box-choice" data-name="${n}" data-capacity="${c}" data-price="${p}"><h3>${n}</h3><p>${c} compartments · From ${money(p)}<br>Forest, ivory and burgundy options</p></button>`).join('')}</div></section><section class="builder-step" data-builder-step="1"><p class="kicker">Step 2 of 6</p><h2 class="section-title">Fill each compartment.</h2><p id="capacity-note">Choose a box first.</p><div class="ingredient-grid">${DATA.ingredients.map((x,i)=>`<article class="ingredient-option" data-ingredient="${i}"><strong>${x.name}</strong><span>${x.weight} · ${money(x.price)} · ${x.allergen}</span><button aria-label="Add ${x.name}">+</button></article>`).join('')}</div></section><section class="builder-step" data-builder-step="2"><p class="kicker">Step 3 of 6</p><h2 class="section-title">Make the sender visible.</h2><div class="form-grid"><label>Recipient name<input id="builder-name" placeholder="e.g. Ananya"></label><label>Festival greeting<select id="builder-greeting"><option>With thanks</option><option>Happy Diwali</option><option>Welcome to the team</option><option>Warm wishes</option></select></label><label class="wide">Printed message card<textarea id="builder-message" rows="4" placeholder="Your message"></textarea></label><label><input type="checkbox" value="Logo sleeve"> Company logo sleeve</label><label><input type="checkbox" value="Branded ribbon"> Branded ribbon</label><label><input type="checkbox" value="Engraved lid"> Engraved wooden lid</label><label><input type="checkbox" value="Company colours"> Company-colour packaging</label></div></section><section class="builder-step" data-builder-step="3"><p class="kicker">Step 4 of 6</p><h2 class="section-title">Who receives the gifts?</h2><div class="form-grid"><label>Quantity<input id="builder-qty" type="number" min="1" value="1"></label><label>Address route<select><option>One delivery address</option><option>Multiple addresses</option><option>Address collection link</option></select></label><div class="wide upload-zone"><strong>Upload recipient addresses</strong><p>CSV or Excel frontend mock · Download template before production integration.</p><input type="file" id="address-upload" accept=".csv,.xlsx"><p id="upload-status"></p></div><label class="wide"><input type="checkbox"> Same message for every recipient</label></div></section><section class="builder-step" data-builder-step="4"><p class="kicker">Step 5 of 6</p><h2 class="section-title">Plan the arrival.</h2><div class="form-grid"><label>Dispatch preference<select><option>As soon as possible</option><option>Selected date</option><option>Schedule individually</option></select></label><label>Preferred delivery date<input type="date" id="builder-date"></label><label class="wide">Delivery notes<textarea rows="4" placeholder="Cities, windows or event timing"></textarea></label></div></section><section class="builder-step" data-builder-step="5"><p class="kicker">Step 6 of 6</p><h2 class="section-title">Review the complete brief.</h2><div id="builder-review" class="success-panel"></div><button class="btn forest" id="builder-add">Save configuration to cart</button></section><div class="builder-nav"><button class="btn" id="builder-prev">Previous</button><button class="btn forest" id="builder-next">Continue</button></div>`}
function corporate(){return `<section class="corporate-hero"><div class="corporate-hero-copy"><p class="kicker">Corporate gifting across India</p><h1 class="display">Corporate gifts that feel genuinely considered.</h1><p class="lede">Create premium dry-fruit gifts for clients, employees, leadership teams, events and festive occasions—with custom branding and coordinated delivery across India.</p><div class="hero-actions"><a class="btn light" href="corporate-quote.html">Request a quote</a><a class="btn light" href="gift-boxes.html">Browse corporate boxes</a></div></div><div class="corporate-hero-media">${image('assets/koshra-corporate-desk.jpg','KOSHRA branded corporate gift on an executive desk')}</div></section><section class="editorial-section"><div class="shell">${sectionHead('Where gifting works','Different programmes. One clear operating system.','Employee appreciation, client retention, leadership gifting, joining kits, conferences, festivals, dealer programmes and milestone events.')}<div class="quality-grid">${['Employee appreciation','Client retention','Leadership gifting','Joining kits','Conference speakers','Festival programmes','Dealer and partner gifts','Wedding and event gifting'].map((x,i)=>`<article><span class="kicker">0${i+1}</span><h3>${x}</h3><p>Box, message, quantity and delivery planning shaped to this specific recipient context.</p></article>`).join('')}</div></div></section><section class="corporate-feature"><div class="corporate-copy"><p class="kicker">What the corporate desk manages</p><h2 class="section-title">Branding is only one part of the work.</h2><div class="service-list">${['Custom packaging','Logo sleeves','Branded ribbons','Printed cards','Product combinations','Volume pricing','GST invoicing','Multiple addresses','Scheduled dispatch','Pan-India fulfilment','Dietary coordination','Dedicated support'].map(x=>`<span>${x}</span>`).join('')}</div></div><div class="corporate-media">${image('assets/koshra-dispatch.jpg','KOSHRA corporate dry-fruit gifts arranged for multi-address dispatch')}</div></section><section class="editorial-section"><div class="shell">${sectionHead('From brief to dispatch','Five approval points. No mystery hand-offs.','A procurement-friendly process keeps product, branding, address and delivery decisions visible.')}<div class="process-strip">${['Share requirements','Receive recommendations','Approve product + branding','Upload recipients','Track preparation'].map((x,i)=>`<article><b>0${i+1}</b><h3>${x}</h3><p>${['Quantity, budget, occasion and date.','Shortlist, sample route and pricing.','Artwork, message and physical sample.','Excel, manual entry or collection link.','Milestones through dispatch.'][i]}</p></article>`).join('')}</div></div></section><section class="editorial-section"><div class="shell">${sectionHead('Recommendations by budget','Start with what each gift needs to achieve.','Every tier keeps product and presentation concrete; final corporate pricing depends on quantity, branding and delivery complexity.')}<div class="budget-table">${[['Under ₹1,000','Compact gratitude boxes'],['₹1,000–₹1,500','Four-part appreciation boxes'],['₹1,500–₹2,500','Client and executive formats'],['₹2,500–₹5,000','Wooden and presentation boxes'],['₹5,000+','Celebration trunks and bespoke programmes']].map(x=>`<a href="gift-boxes.html"><strong>${x[0]}</strong><span>${x[1]}</span><b>View →</b></a>`).join('')}</div></div></section><section class="case-study"><div class="case-study-copy"><span class="placeholder-label">Sample case study layout — replace with verified project</span><h2 class="section-title">A multi-city employee appreciation brief.</h2><p>No company name or result is claimed. This layout shows where approved project evidence would live.</p><div class="case-grid">${[['Client type','HR / People team'],['Gift count','[To be supplied]'],['Delivery cities','[To be supplied]'],['Customisation','Logo sleeve + card'],['Timeline','[To be supplied]'],['Result','Verified outcome required']].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div></div><div class="case-study-media">${image('assets/koshra-dispatch.jpg','Sample layout showing KOSHRA gift boxes prepared for dispatch')}</div></section><section class="editorial-section"><div class="shell">${sectionHead('Corporate FAQ','Questions procurement teams ask early.','Answers are concept copy and must be aligned to actual operating policy before launch.')}${faqList(true)}</div></section>${finalCTA()}`}
function faqList(corp=false){const rows=corp?[['What is the minimum order quantity?','Ready-made corporate formats begin at 10 gifts; custom branding routes typically begin at 25–50, subject to verification.'],['Can we add our company logo?','Yes, through sleeves, ribbons, cards or engraving after artwork approval.'],['Do you provide GST invoices?','The production site should collect GSTIN and issue compliant invoices after client setup.'],['Can you ship to multiple addresses?','Yes. The interface supports address upload; logistics integration is still required.'],['Can gifts arrive on a specific date?','Scheduled delivery is planned subject to serviceability and lead time.'],['Can you accommodate dietary restrictions?','Product suitability must be confirmed against final ingredients and allergen controls.']]:[['How long do gift boxes stay fresh?','Shelf life varies by product. The exact verified duration appears on each final product label.'],['Can I choose a delivery date?','The demo accepts a preferred date. Production requires courier serviceability checks.'],['Is a message card included?','Yes, one printed message card is included in the concept.'],['Can I return a personalised gift?','Personalised food products are generally non-returnable except for damage or fulfilment error; final policy needs legal review.'],['Is cash on delivery available?','COD is configurable and not assumed available.'],['Are the boxes vegetarian?','Final ingredient and manufacturing declarations must be verified before launch.']];return `<div class="accordion">${rows.map(([q,a])=>`<button aria-expanded="false">${q}<span>+</span></button><div class="accordion-panel">${a}</div>`).join('')}</div>`}
function quoteForm(){return `${pageHero('Corporate quote','Tell us what the gifting programme needs to do.','A grouped brief for product, quantity, branding, recipient logistics and timing—without a “book a demo” detour.','assets/koshra-dispatch.jpg')}<div class="quote-layout"><section class="form-panel"><form id="quote-form" class="form-grid" novalidate>${[['Full name','text'],['Company name','text'],['Work email','email'],['Phone number','tel'],['WhatsApp number','tel'],['Number of gifts','number']].map(([n,t])=>`<label>${n}<input name="${n}" type="${t}" required></label>`).join('')}<label>Budget per gift<select name="Budget"><option value="">Select budget</option><option>Under ₹1,000</option><option>₹1,000–₹1,500</option><option>₹1,500–₹2,500</option><option>₹2,500–₹5,000</option><option>₹5,000+</option></select></label><label>Occasion<select name="Occasion"><option>Diwali</option><option>Employee appreciation</option><option>Client gifting</option><option>Conference</option><option>Wedding</option></select></label><label>Required delivery date<input name="Date" type="date" required></label><label>Delivery cities<input name="Cities" placeholder="e.g. Mumbai, Pune, Bengaluru"></label><label>Address route<select><option>Single address</option><option>Multiple addresses</option><option>Not decided</option></select></label><label>Branding required<select><option>No</option><option>Logo sleeve</option><option>Ribbon + card</option><option>Custom packaging</option></select></label><label>Preferred packaging<select><option>Open to recommendation</option><option>Rigid box</option><option>Wooden box</option><option>Kraft box</option><option>Festive trunk</option></select></label><label>GST invoice required<select><option>Yes</option><option>No</option></select></label><label>Sample required<select><option>Yes</option><option>No</option><option>Need advice</option></select></label><label class="wide">Dietary requirements<input name="Dietary" placeholder="Vegan, no chocolate, allergies to consider"></label><label class="wide">Preferred products and instructions<textarea name="Message" rows="5"></textarea></label><p class="form-error wide" id="quote-error" role="alert"></p><button class="btn forest wide" type="submit">Send gifting requirement</button></form><div id="quote-success" hidden></div></section><aside class="form-aside"><p class="kicker">What happens next</p><h2 class="section-title">A useful response, not a sales sequence.</h2><ol class="numbered-process"><li><b>01</b><span>Requirement reviewed against quantity, budget and date.</span></li><li><b>02</b><span>Suitable boxes, customisation and pricing shared.</span></li><li><b>03</b><span>Sample and artwork approval route confirmed.</span></li></ol><p><strong>Phone:</strong> +91 [CLIENT NUMBER]</p><p><strong>Email:</strong> corporate@[brand-domain].in</p><a class="btn" href="#">Continue on WhatsApp</a></aside></div>`}
function cartPage(){const cart=getCart();if(!cart.length)return `${pageHero('Your bag','A clear place for every gift detail.','Your bag is currently empty. Start with a ready-made box or configure one from scratch.','assets/koshra-corporate-desk.jpg')}<div class="empty-state"><div><h2>Your bag is empty.</h2><p>Choose a ready-made box or build a personalised gift.</p><a class="btn forest" href="shop.html">Shop gift boxes</a> <a class="btn" href="build-your-box.html">Build your box</a></div></div>`;const subtotal=cart.reduce((s,x)=>s+(DATA.products.find(p=>p.id===x.id)?.price||0)*x.qty,0);return `${pageHero('Your bag','Review the product, message and timing.','Personalisation, quantity and delivery details stay visible before checkout.','assets/koshra-corporate-desk.jpg')}<div class="cart-layout"><section class="cart-items">${cart.map((x,i)=>{const p=DATA.products.find(p=>p.id===x.id);return `<article class="cart-line">${image(p.image,p.name)}<div><h3>${p.name}</h3><p>${x.custom?.message||'Complimentary message card not yet written.'}</p><label>Quantity <input class="cart-qty" data-index="${i}" type="number" min="1" value="${x.qty}"></label><button class="text-button cart-remove" data-index="${i}">Remove</button> · <button class="text-button">Save for later</button></div><strong>${money(p.price*x.qty)}</strong></article>`}).join('')}</section><aside class="cart-summary"><h2 class="section-title">Order summary</h2><dl><div><dt>Subtotal</dt><dd>${money(subtotal)}</dd></div><div><dt>Estimated shipping</dt><dd>Calculated at checkout</dd></div><div><dt>GST</dt><dd>Shown after billing details</dd></div></dl><label>Promo code<input placeholder="Enter code"></label><button class="btn forest block" onclick="location.href='checkout.html'">Continue to checkout</button>${cart.reduce((a,b)=>a+b.qty,0)>=25?'<p class="success-panel">This quantity may qualify for corporate pricing. <a href="corporate-quote.html"><strong>Request a quote →</strong></a></p>':''}</aside></div>`}
function checkout(){const cart=getCart(),subtotal=cart.reduce((s,x)=>s+(DATA.products.find(p=>p.id===x.id)?.price||0)*x.qty,0);return `${pageHero('Checkout','Delivery details before payment.','This is a complete frontend checkout demonstration. Payment, tax and courier integrations are not connected.','assets/koshra-hero.jpg')}<div class="checkout-layout"><form class="checkout-form" id="checkout-form"><section class="checkout-section"><h2>1. Contact</h2><div class="form-grid"><label>Email<input type="email" required></label><label>Indian mobile number<input type="tel" pattern="[0-9]{10}" required></label></div></section><section class="checkout-section"><h2>2. Delivery address</h2><div class="form-grid"><label>Full name<input required></label><label>PIN code<input maxlength="6" required></label><label class="wide">Address<input required></label><label>City<input required></label><label>State<select><option>Maharashtra</option><option>Gujarat</option><option>Karnataka</option><option>Delhi</option><option>Other</option></select></label><label class="wide"><input type="checkbox"> Deliver to multiple addresses</label></div></section><section class="checkout-section"><h2>3. Billing and GST</h2><div class="form-grid"><label>GST invoice<select><option>No</option><option>Yes</option></select></label><label>GSTIN<input placeholder="22AAAAA0000A1Z5"></label></div></section><section class="checkout-section"><h2>4. Gift and delivery</h2><div class="form-grid"><label>Preferred date<input type="date"></label><label class="wide">Gift message<textarea rows="3"></textarea></label><label class="wide">Order notes<textarea rows="3"></textarea></label></div></section><section class="checkout-section"><h2>5. Payment method</h2><div class="payment-options">${['UPI','Credit / debit card','Net banking','Wallet','Corporate bank transfer'].map(x=>`<label><input type="radio" name="payment" required> ${x}</label>`).join('')}</div><p><small>Payment selection is a visual placeholder. No transaction will be processed.</small></p></section><label><input type="checkbox" required> I agree to the terms, shipping policy and privacy notice.</label><button class="btn forest block" type="submit">Review payment placeholder</button></form><aside class="order-summary"><h2 class="section-title">Your gifts</h2>${cart.map(x=>{const p=DATA.products.find(p=>p.id===x.id);return `<div class="cart-drawer-line">${image(p.image,p.name)}<span>${p.name}<br>Qty ${x.qty} · ${money(p.price*x.qty)}</span></div>`}).join('')||'<p>No cart items. Checkout remains visible for UI review.</p>'}<dl><div><dt>Subtotal</dt><dd>${money(subtotal)}</dd></div><div><dt>Shipping</dt><dd>To be calculated</dd></div><div><dt>Tax</dt><dd>To be calculated</dd></div></dl></aside></div>`}
function contentPage(type){const map={about:['Our story','A gifting house built around what the gesture needs to say.','KOSHRA is a concept for a modern Indian dry-fruit business serving personal and corporate gifting. The interface puts product, message and fulfilment detail on equal footing.','assets/koshra-corporate-desk.jpg'],quality:['Ingredients and quality','Good gifting begins with details that can be verified.','Sourcing, freshness, packing and storage information remain editable until the business supplies approved specifications.','assets/dried-fruits-unsplash.jpg'],packaging:['Packaging and personalisation','Make the sender visible without overwhelming the gift.','Sleeves, ribbons, cards, engraving and company colours are treated as a coordinated system.','assets/koshra-unboxing.jpg'],delivery:['Delivery information','Plan the arrival as carefully as the box.','Pan-India messaging, PIN-code checks, scheduled delivery and multi-address dispatch need final logistics integration.','assets/koshra-dispatch.jpg'],privacy:['Privacy policy','A clear placeholder for responsible data handling.','This concept collects no real customer data. Replace this page with counsel-approved policy before launch.','assets/koshra-corporate-desk.jpg'],terms:['Terms and conditions','Commercial terms should be readable before payment.','Product, payment, personalisation, cancellation and liability terms need client and legal approval.','assets/koshra-hero.jpg'],returns:['Shipping and returns','Set expectations before a food gift leaves the studio.','This placeholder distinguishes damage and fulfilment errors from returns of personalised food products.','assets/koshra-dispatch.jpg']};const [k,h,p,img]=map[type];const prose={about:`<h2>Why this brand direction exists</h2><p>Premium gifting often becomes decorative before it becomes useful. KOSHRA starts with recipient, quantity, budget and delivery date, then brings packaging craft around those facts.</p><h2>Modern Indian, not themed Indian</h2><p>Forest green, ivory, walnut and burgundy reference materials and celebrations without turning every occasion into festival ornament. The serif carries warmth; the operational type remains direct.</p><h2>What must be supplied before launch</h2><p>Founding story, location, contact details, production photography, verified operating claims and approved social accounts.</p>`,quality:`<h2>Ingredient sourcing</h2><p><span class="placeholder-label">Client verification required</span></p><p>Document supplier selection, grades, origin where supportable, incoming checks and batch traceability.</p><div class="quality-grid">${[['Freshness','Packing date, best-before and storage conditions'],['Hygienic packing','Facility controls and handling process'],['Food safety','FSSAI number and applicable declarations'],['Allergens','Tree nuts, seeds, soy and milk by SKU'],['Shelf life','Exact approved duration for every product'],['Storage','Cool, dry place and seal instructions']].map(x=>`<article><h3>${x[0]}</h3><p>${x[1]}</p><span class="placeholder-label">Verify before launch</span></article>`).join('')}</div>`,packaging:`<h2>Five personalisation layers</h2><div class="quality-grid">${[['Logo sleeve','Removable paper branding around the closed box'],['Branded ribbon','Company colour and repeat mark'],['Printed card','Shared or recipient-specific message'],['Engraved lid','For approved wooden-box programmes'],['Custom colour','Production subject to quantity and lead time'],['Address label','Designed for discreet, clear fulfilment']].map(x=>`<article><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div><h2>The approval route</h2><p>Artwork check → digital mockup → optional physical sample → written approval → bulk production.</p>`,delivery:`<h2>Retail orders</h2><p>Dispatch estimates are shown on every product. Courier serviceability, shipping charge and expected arrival must be calculated against the final PIN code.</p><h2>Corporate and multi-address orders</h2><p>Recipient data can arrive by template upload, manual entry or a recipient collection link. The production version should validate addresses before packing begins.</p><h2>Scheduled delivery</h2><p>Preferred dates are requests until courier and location checks confirm them. Event-critical programmes should include a delivery buffer.</p>`,privacy:`<h2>Data collected</h2><p>Contact, order, delivery, billing, recipient and optional corporate information may be collected only for the purposes disclosed at the point of entry.</p><h2>Recipient data</h2><p>Multiple-address files require restricted access, retention rules and a deletion process. No data is transmitted by this concept.</p><h2>Cookies and services</h2><p>List analytics, payment, courier, CRM and marketing providers after integrations are selected.</p>`,terms:`<h2>Concept status</h2><p>This UI is a demonstration. Products, prices, operations and claims require owner approval before commercial use.</p><h2>Orders and payment</h2><p>Define order acceptance, payment capture, taxes, invoicing, pricing errors and cancellation windows.</p><h2>Food and personalisation</h2><p>Confirm ingredient, allergen, storage, shelf-life, artwork and message responsibilities.</p>`,returns:`<h2>Shipping</h2><p>Publish service areas, dispatch cut-offs, courier partners, charges and delivery estimates after operational confirmation.</p><h2>Damage or incorrect fulfilment</h2><p>Specify the reporting window, evidence required and replacement or refund process.</p><h2>Personalised food products</h2><p>These are generally unsuitable for change-of-mind returns. The final policy must comply with applicable Indian law.</p>`}[type];return `${pageHero(k,h,p,img)}<section class="content-page"><div class="shell prose-grid"><nav class="prose-nav"><a href="about.html">Our story</a><a href="ingredients-quality.html">Ingredients & quality</a><a href="packaging-personalisation.html">Packaging</a><a href="delivery.html">Delivery</a><a href="faq.html">FAQs</a><a href="contact.html">Contact</a></nav><article class="prose">${prose}</article></div></section>`}
function faqPage(){return `${pageHero('Frequently asked questions','Useful answers before the gift is chosen.','Retail, personalisation, delivery and corporate questions gathered in one clear reference.','assets/koshra-unboxing.jpg')}<section class="content-page"><div class="shell">${faqList(false)}<div class="state-demo"><article><p class="kicker">Delivery unavailable</p><h3>This PIN code needs a manual check.</h3><p>Contact the gifting desk for alternate routing.</p></article><article><p class="kicker">Low stock</p><h3>12 boxes remain at this dispatch speed.</h3><p>Larger quantities move to coordinated ordering.</p></article><article><p class="kicker">Quote required</p><h3>Custom programmes begin with a brief.</h3><p>Quantity, date and branding determine feasibility.</p></article><article><p class="kicker">Loading catalogue</p><h3>Curating the available boxes.</h3><p>A clear loading state holds the product grid in place.</p></article><article><p class="kicker">Payment failed</p><h3>No amount was charged.</h3><p>Retry the payment method or return to the secure checkout.</p></article><article><p class="kicker">Order confirmed</p><h3>Your gifting order is in preparation.</h3><p>A confirmation reference and dispatch updates follow by email.</p></article></div></div></section>`}
function contact(){return `${pageHero('Contact','Reach the right gifting desk.','Retail orders, corporate programmes and delivery support each get a practical route.','assets/koshra-corporate-desk.jpg')}<div class="contact-grid"><aside class="contact-methods"><p class="kicker">Contact placeholders</p><h2 class="section-title">KOSHRA gifting house</h2><p>Retail: hello@[brand-domain].in</p><p>Corporate: corporate@[brand-domain].in</p><p>Phone / WhatsApp: +91 [CLIENT NUMBER]</p><p>Studio: [CLIENT ADDRESS], India</p><p>Hours: [CLIENT TO PROVIDE]</p></aside><section class="form-panel"><form class="form-grid" id="contact-form"><label>Name<input required></label><label>Email<input type="email" required></label><label>Phone<input type="tel"></label><label>Topic<select><option>Retail order</option><option>Corporate gifting</option><option>Delivery help</option><option>Product question</option></select></label><label class="wide">Message<textarea rows="6" required></textarea></label><button class="btn forest wide">Send message</button></form></section></div>`}
function account(){return `${pageHero('Account','Your orders, addresses and saved gifts.','A front-end account interface ready for authentication and commerce integration.','assets/koshra-corporate-desk.jpg')}<section class="login-box"><p class="kicker">Sign in</p><h1 class="section-title">Welcome back.</h1><form class="form-grid" id="login-form"><label class="wide">Email<input type="email" required></label><label class="wide">Password<input type="password" required></label><button class="btn forest wide">Sign in</button></form><p><a href="#">Forgot password?</a> · <a href="#">Create account</a></p><p><small>Authentication is not connected in this concept.</small></p></section>`}
function track(){return `${pageHero('Order tracking','Follow preparation before the courier journey.','Enter a concept order number to see the intended tracking experience.','assets/koshra-dispatch.jpg')}<section class="track-box"><p class="kicker">Try KOS-240826</p><h1 class="section-title">Track an order</h1><form id="track-form"><label>Order number<input id="track-id" required placeholder="KOS-240826"></label><button class="btn forest">Check status</button></form><div id="track-result"></div></section>`}
function route(){const routes={index:home,shop:()=>shop(),'gift-boxes':()=>shop('Gift boxes for considered occasions','Gift Boxes'),collections,product:productDetail,'build-your-box':builder,'corporate-gifting':corporate,'corporate-quote':quoteForm,cart:cartPage,checkout,about:()=>contentPage('about'),'ingredients-quality':()=>contentPage('quality'),'packaging-personalisation':()=>contentPage('packaging'),delivery:()=>contentPage('delivery'),faq:faqPage,contact,account,'track-order':track,privacy:()=>contentPage('privacy'),terms:()=>contentPage('terms'),'shipping-returns':()=>contentPage('returns')};return (routes[page]||home)()}
function bindCommon(){$$('.quick-add').forEach(b=>b.onclick=()=>addCart(b.dataset.id));$$('.accordion button').forEach(b=>b.onclick=()=>{const p=b.nextElementSibling,o=p.classList.toggle('open');b.setAttribute('aria-expanded',o);$('span',b).textContent=o?'−':'+'});$('.gift-finder')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);location.href=`collections.html?occasion=${encodeURIComponent(d.get('occasion'))}&quantity=${encodeURIComponent(d.get('quantity'))}`});$('#sort-products')?.addEventListener('change',e=>{const cards=$$('.product-card',$('#shop-grid'));cards.sort((a,b)=>{const pa=DATA.products.find(p=>a.dataset.id===p.id),pb=DATA.products.find(p=>b.dataset.id===p.id);return e.target.value==='low'?pa.price-pb.price:e.target.value==='high'?pb.price-pa.price:pa.name.localeCompare(pb.name)}).forEach(c=>$('#shop-grid').append(c))});$$('.view-toggle').forEach(x=>x.onclick=()=>$('#shop-grid').classList.toggle('list-view',x.dataset.view==='list'));$$('.filters input').forEach(x=>x.onchange=applyFilters);$$('.clear-filters').forEach(x=>x.onclick=()=>{$$('.filters input').forEach(x=>x.checked=false);applyFilters()});$('.mobile-filter')?.addEventListener('click',()=>{const f=$('.filters');f.classList.add('mobile-open');$('.backdrop').classList.add('open');document.body.classList.add('locked')});$('.filter-close')?.addEventListener('click',closePanels);$('#add-product')?.addEventListener('click',e=>addCart(e.target.dataset.id,Math.max(1,+$('#product-qty').value),{message:$('#gift-message').value,date:$('#delivery-date').value,personalise:$('#personalise').value}));$('[data-sticky-add]')?.addEventListener('click',e=>addCart(e.target.dataset.stickyAdd));$('#pin-check')?.addEventListener('input',e=>{$('#pin-result').textContent=e.target.value.length===6?(/^[1-9][0-9]{5}$/.test(e.target.value)?'Serviceability check available at checkout':'Invalid PIN code'):''});$$('.cart-qty').forEach(x=>x.onchange=()=>{const c=getCart();c[+x.dataset.index].qty=Math.max(1,+x.value);saveCart(c);location.reload()});$$('.cart-remove').forEach(x=>x.onclick=()=>{const c=getCart();c.splice(+x.dataset.index,1);saveCart(c);location.reload()});$('#quote-form')?.addEventListener('submit',submitQuote);$('#checkout-form')?.addEventListener('submit',e=>{e.preventDefault();toast('Payment integration placeholder — no charge made')});$('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();e.target.reset();toast('Message noted — frontend demo only')});$('#login-form')?.addEventListener('submit',e=>{e.preventDefault();toast('Account authentication is not connected')});$('#track-form')?.addEventListener('submit',e=>{e.preventDefault();$('#track-result').innerHTML=`<div class="status-track"><div class="status-step"><strong>Order confirmed</strong><p>Your gifting details are recorded.</p></div><div class="status-step"><strong>Personalisation review</strong><p>Artwork approval is the current milestone.</p></div><div class="status-step"><strong>Preparation</strong><p>Begins after approval.</p></div><div class="status-step"><strong>Dispatch</strong><p>Courier tracking will appear here.</p></div></div>`});if(page==='build-your-box')initBuilder()}
function filterMatch(p,group,value){const v=value.toLowerCase();if(group==='Price'){if(v.startsWith('under'))return p.price<1000;if(v.startsWith('₹1,000'))return p.price>=1000&&p.price<2000;if(v.startsWith('₹2,000'))return p.price>=2000&&p.price<5000;return p.price>=5000}if(group==='Occasion'){const map={'client gifting':'client-gifting','employee gifting':'employee','weddings':'wedding','diwali':'diwali'};return p.tags.includes(map[v])}if(group==='Product type')return p.category.toLowerCase()===v.replace('gift boxes','gift boxes').replace('dry fruits','dry fruits');if(v==='personalisation')return p.personalise;if(v==='ready to dispatch')return p.stock.toLowerCase().includes('ready');return p.tags.includes(v)}
function applyFilters(){const selected={};$$('.filters input:checked').forEach(x=>(selected[x.dataset.group]??=[]).push(x.value));let shown=0;$$('#shop-grid .product-card').forEach(c=>{const p=DATA.products.find(p=>p.id===c.dataset.id);const ok=Object.entries(selected).every(([g,vals])=>vals.some(v=>filterMatch(p,g,v)));c.hidden=!ok;if(ok)shown++});$('#product-count').textContent=`${shown} gifts`;$('#empty-products').hidden=shown>0}
function submitQuote(e){e.preventDefault();const req=$$('input[required],select[required]',e.target),bad=req.filter(x=>!x.value);if(bad.length){$('#quote-error').textContent='Complete the required contact, quantity and delivery fields.';bad[0].focus();return}const data=new FormData(e.target),ref=`KQ-${String(Date.now()).slice(-6)}`;e.target.hidden=true;$('#quote-success').hidden=false;$('#quote-success').innerHTML=`<div class="success-panel"><p class="kicker">Requirement received · Demo</p><h2 class="section-title">Reference ${ref}</h2><p><strong>${data.get('Company name')}</strong> · ${data.get('Number of gifts')} gifts · ${data.get('Budget')}</p><p>Next step: a gifting coordinator would review product fit, branding and delivery feasibility before sharing recommendations.</p><a class="btn forest" href="#">Continue on WhatsApp</a></div>`}
function initBuilder(){let step=0,state=JSON.parse(localStorage.getItem('koshra-builder')||'{"box":null,"ingredients":[],"qty":1}');const save=()=>{localStorage.setItem('koshra-builder',JSON.stringify(state));renderBuilder()};$$('.box-choice').forEach(b=>b.onclick=()=>{state.box={name:b.dataset.name,capacity:+b.dataset.capacity,price:+b.dataset.price};state.ingredients=state.ingredients.slice(0,state.box.capacity);save()});$$('.ingredient-option button').forEach((b,i)=>b.onclick=()=>{if(!state.box)return toast('Choose a box first');const idx=state.ingredients.indexOf(i);if(idx>=0)state.ingredients.splice(idx,1);else if(state.ingredients.length<state.box.capacity)state.ingredients.push(i);else return toast('Every compartment is already filled');save()});$$('[data-step]').forEach(b=>b.onclick=()=>go(+b.dataset.step));$('#builder-prev').onclick=()=>go(Math.max(0,step-1));$('#builder-next').onclick=()=>go(Math.min(5,step+1));$('#builder-qty').onchange=e=>{state.qty=Math.max(1,+e.target.value);save()};$('#address-upload').onchange=e=>{$('#upload-status').textContent=e.target.files[0]?.name.endsWith('.csv')||e.target.files[0]?.name.endsWith('.xlsx')?`${e.target.files[0].name} ready for validation.`:'Invalid file. Upload CSV or XLSX.'};$('#builder-add').onclick=()=>{if(!state.box||!state.ingredients.length)return toast('Complete box and contents first');addCart('bespoke',state.qty,{builder:state});localStorage.removeItem('koshra-builder');};function go(n,shouldScroll=true){step=n;$$('.builder-step').forEach((x,i)=>x.classList.toggle('active',i===step));$$('[data-step]').forEach((x,i)=>x.classList.toggle('active',i===step));$('#builder-prev').style.visibility=step===0?'hidden':'visible';$('#builder-next').style.visibility=step===5?'hidden':'visible';renderBuilder();if(shouldScroll)window.scrollTo({top:$('.builder-layout').offsetTop,behavior:'smooth'})}function renderBuilder(){$$('.box-choice').forEach(b=>b.classList.toggle('selected',state.box?.name===b.dataset.name));$$('.ingredient-option').forEach((x,i)=>x.classList.toggle('selected',state.ingredients.includes(i)));$('#capacity-note').textContent=state.box?`${state.ingredients.length} of ${state.box.capacity} compartments selected.`:'Choose a box first.';const slots=state.box?.capacity||4;$('#preview-box').innerHTML=Array.from({length:slots},(_,i)=>`<div class="preview-slot">${state.ingredients[i]!=null?DATA.ingredients[state.ingredients[i]].name:'—'}</div>`).join('');const total=(state.box?.price||0)+state.ingredients.reduce((s,i)=>s+DATA.ingredients[i].price,0);$('#builder-total').textContent=money(total*(state.qty||1));$('#preview-details').innerHTML=state.box?`<p><strong>${state.box.name}</strong><br>${state.ingredients.map(i=>DATA.ingredients[i].name).join(' · ')||'Choose contents'}<br>Quantity ${state.qty||1}</p>`:'<p>Choose a box to begin.</p>';$('#builder-review').innerHTML=`<p><strong>Box:</strong> ${state.box?.name||'Not selected'}</p><p><strong>Contents:</strong> ${state.ingredients.map(i=>DATA.ingredients[i].name).join(', ')||'Not selected'}</p><p><strong>Quantity:</strong> ${state.qty||1}</p><p><strong>Total:</strong> ${money(total*(state.qty||1))}</p>${(state.qty||1)>=50?'<p class="placeholder-label">Corporate quote recommended</p>':''}`}renderBuilder();go(0,false)}
document.addEventListener('DOMContentLoaded',()=>{initShell();$('#content').innerHTML=route();bindCommon();document.title=`${({index:'Thoughtful Gifts',shop:'Shop All','gift-boxes':'Gift Boxes',collections:'Collections',product:'Product','build-your-box':'Build Your Box','corporate-gifting':'Corporate Gifting','corporate-quote':'Corporate Quote',cart:'Cart',checkout:'Checkout',about:'Our Story','ingredients-quality':'Ingredients & Quality','packaging-personalisation':'Packaging & Personalisation',delivery:'Delivery',faq:'FAQs',contact:'Contact',account:'Account','track-order':'Track Order',privacy:'Privacy',terms:'Terms','shipping-returns':'Shipping & Returns'}[page]||'Gifting')} — KOSHRA`;});
